import React, { forwardRef } from 'react';
import { isElement } from 'react-is';

import type { DataTestId } from '../../../core/types/data-props.js';
import type { StylingProps } from '../../../core/types/styling-props.js';
import type { WithChildren } from '../../../core/types/with-children.js';

//#region Typings
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface EmptyStateTitleProps
  extends WithChildren,
    StylingProps,
    DataTestId {}
//#endregion Typings

/**
 * Typeguard function that will check if a React.Node is a EmptyState.Title
 * @internal
 */
export function _isEmptyStateTitle(
  child: React.ReactNode,
): child is React.ReactElement<EmptyStateTitleProps> {
  return isElement(child) && child.type === Title;
}

/** The title slot of the EmptyState component. */
export const Title =
  /* @__PURE__ */
  forwardRef<HTMLDivElement, EmptyStateTitleProps>((props, forwardedRef) => {
    const {
      children,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
    } = props;

    return (
      <div
        ref={forwardedRef}
        className={consumerClassName}
        style={consumerStyle}
        data-testid={dataTestId}
      >
        {children}
      </div>
    );
  });

(Title as typeof Title & { displayName: string }).displayName =
  'EmptyState.Title';
